const item = $input.first().json;

function getParsedFeedMetadata() {
  try {
    return $('Parse RSS Items').first().json;
  } catch (_) {
    try {
      return $items('Parse RSS Items')[0].json;
    } catch (_) {
      return {};
    }
  }
}

function extractJson(value) {
  if (value && typeof value === 'object' && (value.must_read_items || value.top_themes || value.document_title)) {
    return value;
  }

  const raw = String(value?.response || value?.text || value?.output || value?.result || value?.message?.content || '').trim();
  if (!raw) throw new Error('AI did not return text or structured JSON.');

  const cleaned = raw
    .replace(/^```[a-zA-Z]*\n?/, '')
    .replace(/```$/, '')
    .trim();

  try {
    return JSON.parse(cleaned);
  } catch (_) {
    const firstBrace = cleaned.indexOf('{');
    const lastBrace = cleaned.lastIndexOf('}');
    if (firstBrace >= 0 && lastBrace > firstBrace) {
      return JSON.parse(cleaned.slice(firstBrace, lastBrace + 1));
    }
  }

  throw new Error('AI did not return usable JSON. Rerun the workflow or use a model that supports JSON output.');
}

function asList(value, fallback) {
  if (Array.isArray(value)) {
    const cleaned = value.map((item) => String(item).trim()).filter(Boolean);
    if (cleaned.length) return cleaned;
  }
  if (typeof value === 'string' && value.trim()) {
    return value.split('\n').map((item) => item.replace(/^[-*]\s*/, '').trim()).filter(Boolean);
  }
  return fallback;
}

function bulletList(items) {
  return asList(items, ['None added.']).map((item) => '- ' + item).join('\n');
}

function mustReadMarkdown(items) {
  if (!Array.isArray(items) || items.length === 0) return '- None selected.';
  return items.map((item) => {
    return [
      `- **${item.title || 'Untitled item'}**${item.link ? ` - ${item.link}` : ''}`,
      `  - Why it matters: ${item.why_it_matters || 'Review before opening.'}`,
      `  - Practical use: ${item.practical_use || 'Save or adapt if useful.'}`
    ].join('\n');
  }).join('\n');
}

function summaryMarkdown(items) {
  if (!Array.isArray(items) || items.length === 0) return '- None added.';
  return items.map((item) => `- **${item.title || 'Untitled item'}**: ${item.summary || 'No summary provided.'}`).join('\n');
}

const feedMetadata = getParsedFeedMetadata();
const parsed = extractJson(item);
const nextSteps = asList(parsed.next_steps, ['Open the strongest item.', 'Save useful links.', 'Turn one idea into a note or draft.']);

const markdown = [
  '## Top Themes',
  bulletList(parsed.top_themes),
  '',
  '## Must-Read Items',
  mustReadMarkdown(parsed.must_read_items),
  '',
  '## Quick Summaries',
  summaryMarkdown(parsed.quick_summaries),
  '',
  '## Workflow Or Content Ideas',
  bulletList(parsed.workflow_or_content_ideas),
  '',
  '## Parked Items',
  bulletList(parsed.parked_items),
  '',
  '## Things To Verify',
  bulletList(parsed.things_to_verify),
  '',
  '## CTA',
  parsed.cta || 'Open one item and decide whether to save, act, or ignore it.'
].join('\n');

return [{
  json: {
    workflow_name: 'GP-WF-003 - RSS Research Digest',
    created_at: new Date().toISOString(),
    document_title: String(parsed.document_title || 'RSS Research Digest').trim(),
    summary: String(parsed.summary || '').trim(),
    output_markdown: markdown,
    next_steps: nextSteps,
    review_note: String(parsed.review_note || 'Check source links and summaries before relying on this digest.').trim(),
    feed_url: feedMetadata.feed_url || item.feed_url || '',
    item_count: feedMetadata.item_count || item.item_count || 0
  }
}];

const today = new Date();
const date = today.toISOString().slice(0, 10);
const nextSteps = Array.isArray($json.next_steps) ? $json.next_steps : [];

const body = [
  `# ${$json.document_title || 'RSS Research Digest'}`,
  '',
  `Created: ${date}`,
  'Workflow: GP-WF-003 - RSS Research Digest',
  $json.feed_url ? `Feed: ${$json.feed_url}` : '',
  $json.item_count ? `Items parsed: ${$json.item_count}` : '',
  '',
  '## Summary',
  $json.summary || 'No summary returned.',
  '',
  $json.output_markdown || '',
  '',
  '## Next Steps',
  ...(nextSteps.length ? nextSteps.map((step) => `- ${step}`) : ['- Review the digest and open one useful source.']),
  '',
  '## Human Review Note',
  $json.review_note || 'Review source links before using this digest.',
  '',
  'Source: GetPrompting Free Workflow Library'
].filter((line) => line !== '').join('\n');

return [{
  json: {
    ...$json,
    document_title: `GP-WF-003 - RSS Research Digest - ${date}`,
    document_body: body
  }
}];

const httpInput = $input.first().json;
let setup = {};
try { setup = $('Set Workflow Inputs').first().json; } catch (error) {
  try { setup = $items('Set Workflow Inputs')[0].json; } catch (nestedError) { setup = {}; }
}
const input = { ...setup, ...httpInput };
const maxItems = Number(setup.max_items || input.max_items || 6);
const feedUrl = setup.feed_url || input.feed_url || '';
const topicLens = setup.topic_lens || input.topic_lens || '';
const audience = setup.audience || input.audience || '';
const digestGoal = setup.digest_goal || input.digest_goal || '';
const fallbackItems = setup.fallback_items || input.fallback_items || '';

function stripHtml(value) {
  return String(value || '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

function pick(obj, keys) {
  for (const key of keys) {
    if (obj && obj[key] !== undefined && obj[key] !== null) return obj[key];
  }
  return '';
}

const raw = pick(httpInput, ['body', 'data', 'response', 'text', 'content']) || pick(input, ['body', 'data', 'response', 'text', 'content']) || JSON.stringify(httpInput);
let items = [];
const itemBlocks = String(raw).match(/<item[\s\S]*?<\/item>/gi) || String(raw).match(/<entry[\s\S]*?<\/entry>/gi) || [];

for (const block of itemBlocks.slice(0, maxItems)) {
  const title = stripHtml((block.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [,''])[1]);
  let link = stripHtml((block.match(/<link[^>]*>([\s\S]*?)<\/link>/i) || [,''])[1]);
  if (!link) link = stripHtml((block.match(/<link[^>]*href=["']([^"']+)["'][^>]*>/i) || [,''])[1]);
  const date = stripHtml((block.match(/<pubDate[^>]*>([\s\S]*?)<\/pubDate>/i) || block.match(/<updated[^>]*>([\s\S]*?)<\/updated>/i) || block.match(/<published[^>]*>([\s\S]*?)<\/published>/i) || [,''])[1]);
  const description = stripHtml((block.match(/<description[^>]*>([\s\S]*?)<\/description>/i) || block.match(/<summary[^>]*>([\s\S]*?)<\/summary>/i) || block.match(/<content[^>]*>([\s\S]*?)<\/content>/i) || [,''])[1]).slice(0, 700);
  if (title || link || description) items.push({ title, link, date, description });
}

if (items.length === 0 && fallbackItems) {
  items = fallbackItems.split(/\n|\d+\.\s+/).map((text) => stripHtml(text)).filter(Boolean).slice(0, maxItems).map((text, index) => ({
    title: text,
    link: '',
    date: '',
    description: 'Fallback item ' + (index + 1) + ' from the setup node.'
  }));
}

if (items.length === 0) {
  throw new Error('No RSS items could be parsed. Check the feed_url or add fallback_items.');
}

return [{ json: {
  workflow_code: input.workflow_code || 'GP-WF-003',
  workflow_name: input.workflow_name || 'RSS Research Digest',
  feed_url: feedUrl,
  topic_lens: topicLens,
  audience,
  digest_goal: digestGoal,
  max_items: maxItems,
  source_items: items,
  item_count: items.length
}}];
